assert len(p.cards)==54
selection_review=[
 {'pages':[3,4,16],'wording':'any five / any three questions','classification':'exam-level-selection','reason':'All ten offered questions retained for practice.'},
 {'pages':[5],'wording':'List the possible values','classification':'required-answers','reason':'All five products with one ordered outcome are required, not a choice of a subset.'},
 {'pages':[7],'wording':'one of the 5 female names','classification':'event-definition','reason':'Defines the probability event including all five names, not a question-choice pool.'},
 {'pages':[11],'wording':'two points on the circle k and two points on the circle p','classification':'open-examples','reason':'Two arbitrary valid points per circle, not a fixed finite selectable pool; one response and one 5C allocation.'},
 {'pages':[13],'wording':'select the one / give a reason','classification':'answer-selection','reason':'All six correlation coefficients and required reason stay together on one 5B card.'},
 {'pages':[25],'wording':'slopes or distances','classification':'method-choice','reason':'Alternative proofs of one required geometric conclusion, not separate tasks.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All ten offered questions retained.')
 if 'female names' in t:return ('event-definition','All five names define one probability event.')
 if 'or otherwise' in t:return ('method-choice','Alternative methods for one required task.')
 if 'select the one' in t or 'correlation' in t:return ('answer-selection','One response retains all six alternatives and the required reason.')
 if 'one of the beads' in t or 'one bead' in t:return ('required-reference','Identical spherical beads; compute the volume of one bead.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
